mapper.select:
SELECT ChnlCode, ChnlName, ChnlDesc, ChnlUrl, ChnlPolicyCode, SvcCode, DesignId,
       CompCode, LogoImg, MngrName, MngrPhoneNo, MngrMobileNo, MngrFaxNo, MngrEmail,
       MallStartDate, MallEndDate, MemberChnlCode, PrsdntChnlCode, AdjustChnlCode,
       SlnkMallCode, LoginId,
       State, Remark, RegistDate, RegistId, RegistName, ChangeDate, ChangeId, ChangeName
FROM shopion.tStrChnl


        AND SvcCode = #{pSvcCode}


        AND ChnlCode = #{pChnlCode}


        AND DesignId IS NOT NULL


ORDER BY ChnlCode

    LIMIT #{topCnt}


    LIMIT #{startNum}, #{countPerPage}

SELECT COUNT(*)
FROM shopion.tStrChnl


        AND SvcCode = #{pSvcCode}


        AND ChnlCode = #{pChnlCode}


        AND DesignId IS NOT NULL
